getStudentTasks.query:
query getStudentTasks($userId: ID!, $studentIds: [ID!], $filters: TaskFilter, $first: Int, $after: String, $orderByDirection: ORDER_BY_DIRECTION, $type: ENTITY_TYPE_ENUM!) {
  node(id: $userId, type: $type) {
    id
    ... on Student {
      id
      tasks(filters: $filters, first: $first, after: $after, orderByDirection: $orderByDirection) {
        pageInfo {
          hasNextPage
          hasPreviousPage
          startCursor
          endCursor
          __typename
        }
        totalCount
        edges {
          id
          orderDate
          itemType
          item {
            id
            ... on StudentAssignment {
              ...studentAssignmentItem
              __typename
            }
            ... on ProjectDeadline {
              ...projectDeadlineItem
              __typename
            }
            ... on ProjectTaskResponse {
              id
              mappedProject: project {
                id
                projectGroup {
                  id
                  type
                  subType
                  courses {
                    edges {
                      node {
                        id
                        __typename
                      }
                      __typename
                    }
                    __typename
                  }
                  __typename
                }
                __typename
              }
              task {
                ...projectGroupTaskItem
                __typename
              }
              latestSubmissionResponse {
                id
                status
                __typename
              }
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    ... on FamilyMember {
      id
      tasks(filters: $filters, first: $first, after: $after, studentIds: $studentIds, orderByDirection: $orderByDirection) {
        pageInfo {
          hasNextPage
          hasPreviousPage
          startCursor
          endCursor
          __typename
        }
        totalCount
        edges {
          id
          orderDate
          itemType
          item {
            id
            ... on StudentAssignment {
              ...studentAssignmentItem
              __typename
            }
            ... on ProjectDeadline {
              ...projectDeadlineItem
              __typename
            }
            ... on ProjectTaskResponse {
              id
              mappedProject: project {
                id
                projectGroup {
                  id
                  type
                  subType
                  courses {
                    edges {
                      node {
                        id
                        __typename
                      }
                      __typename
                    }
                    __typename
                  }
                  __typename
                }
                __typename
              }
              task {
                ...projectGroupTaskItem
                __typename
              }
              latestSubmissionResponse {
                id
                status
                __typename
              }
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

fragment studentAssignmentItem on StudentAssignment {
  id
  status
  isSubmitted
  isEvaluated
  isSharedWithStudent
  isNewForStudent
  state
  conversation {
    id
    unreadMessageCount
    __typename
  }
  submission {
    id
    status
    statusV2
    __typename
  }
  assignment {
    id
    label
    contentType
    isFixedStartTime
    isStudentSubmissionEnabled
    isTeacherEvaluationEnabled
    deadline
    closeSubmissionDate
    visibility
    state {
      state
      publishedAt
      __typename
    }
    assignedStudents {
      id
      state
      __typename
    }
    course {
      id
      title
      learningCourse {
        id
        title
        academicCourse {
          id
          label
          __typename
        }
        __typename
      }
      __typename
    }
    content {
      ... on Assessment {
        id
        assessmentType {
          id
          value
          __typename
        }
        taskType {
          id
          type
          label
          __typename
        }
        title {
          id
          value
          __typename
        }
        image {
          id
          value
          __typename
        }
        __typename
      }
      ... on AssignmentResource {
        id
        label
        __typename
      }
      __typename
    }
    curriculumProgram {
      id
      curriculum {
        id
        type
        __typename
      }
      __typename
    }
    classDiscussion {
      id
      unreadMessageCount
      __typename
    }
    __typename
  }
  lockingState {
    state
    __typename
  }
  isEvaluationApplicable
  __typename
}

fragment projectDeadlineItem on ProjectDeadline {
  id
  deadline {
    id
    deadlineDate
    title
    description
    isDeadlineAllDay
    __typename
  }
  project {
    id
    projectGroup {
      id
      name
      subType
      type
      courses {
        edges {
          node {
            id
            title
            learningCourse {
              id
              title
              academicCourse {
                id
                label
                __typename
              }
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      subject {
        id
        name
        type
        ibOfferedSubject {
          id
          contentSubject {
            id
            assessmentYearTitle
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    fields(filters: {uids: ["title", "topic"]}) {
      id
      uid
      value
      __typename
    }
    status
    conversation {
      id
      unreadMessageCount
      __typename
    }
    __typename
  }
  __typename
}

fragment projectGroupTaskItem on ProjectGroupTask {
  id
  title
  description
  dueOn
  closesOn
  isStudentSubmissionEnabled
  submission {
    id
    type
    __typename
  }
  __typename
}

getUserCourses.query:
query getUserCourses($id: ID!, $type: ENTITY_TYPE_ENUM!, $filters: CourseFilter, $isCurriculumProgramFree: Boolean! = false, $courseGradeFilters: CourseGradeFilters, $enabledModulesFilters: EnabledModulesFiltersInput) {
  node(id: $id, type: $type) {
    id
    ... on Staff {
      ...staffItem
      __typename
    }
    ... on Student {
      ...studentCourseItem
      __typename
    }
    __typename
  }
}

fragment studentCourseItem on Student {
  id
  courses(orderBy: TITLE, orderByDirection: ASC, filters: $filters) {
    ...courseFeedItem
    isExcludedFromAttendanceCalculation
    __typename
  }
  __typename
}

fragment courseFeedItem on Course {
  id
  title
  primaryGrade(filters: $courseGradeFilters) {
    id
    name
    __typename
  }
  profileImageData {
    url
    icon
    color
    __typename
  }
  grades(filters: $courseGradeFilters) {
    id
    name
    globalGrade {
      id
      uid
      name
      constants
      __typename
    }
    displaySequence
    __typename
  }
  calendar {
    id
    __typename
  }
  curriculumProgram {
    ...curriculumProgramBasicDetailsItem
    __typename
  }
  academicYears {
    ...academicYearItem
    __typename
  }
  subjects {
    id
    name
    type
    __typename
  }
  subjectGroups {
    id
    name
    __typename
  }
  projectGroups {
    ...basicProjectGroupDetails
    __typename
  }
  isDemo
  isRemovedCourseForLoggedInUser
  isArchived
  genericTags {
    id
    label
    type
    __typename
  }
  enabledModules(filters: $enabledModulesFilters)
  learningCourse {
    id
    title
    academicCourse {
      id
      label
      __typename
    }
    gradingPeriods {
      edges {
        node {
          id
          __typename
        }
        __typename
      }
      __typename
    }
    displayMetadata
    isClassFlowEnabled
    __typename
  }
  __typename
}

fragment academicYearItem on AcademicYear {
  id
  startDate
  endDate
  isCurrentAcademicYear
  isUpcomingAcademicYear
  transitionReviewStatus
  label
  __typename
}

fragment curriculumProgramBasicDetailsItem on CurriculumProgram {
  id
  type
  nodeInterfaceType
  label
  acronym
  academicSetupType
  programType
  ... on IbDpCurriculumProgram {
    examSessionMonth
    __typename
  }
  __typename
}

fragment basicProjectGroupDetails on ProjectGroup {
  id
  name
  type
  subType
  curriculumProgram {
    id
    type
    __typename
  }
  __typename
}

fragment staffItem on Staff {
  id
  courses(orderBy: TITLE, orderByDirection: ASC, filters: $filters) {
    ...courseItem
    __typename
  }
  __typename
}

fragment courseItem on Course {
  id
  title
  isArchived
  enabledModules(filters: $enabledModulesFilters)
  grades(filters: $courseGradeFilters) {
    ...gradeItem
    __typename
  }
  curriculumProgram {
    ...curriculumProgramBasicDetailsItem
    __typename
  }
  calendar {
    id
    __typename
  }
  isDemo
  academicYears {
    ...academicYearItem
    __typename
  }
  subjectGroups {
    id
    name
    __typename
  }
  projectGroups {
    ...basicProjectGroupDetails
    __typename
  }
  profileImage
  isRemovedCourseForLoggedInUser
  tags {
    id
    key
    value
    __typename
  }
  subjects {
    id
    name
    __typename
  }
  __typename
}

fragment gradeItem on Grade {
  id
  name
  unitPlanCount(innerUserIdFilter: $id) @include(if: $isCurriculumProgramFree)
  globalGrade {
    id
    constants
    displaySequence
    __typename
  }
  displaySequence
  __typename
}
